message.content:
{
  "timeline": [
    {
      "event_id": 0,
      "text": "台湾海峡中线是上世纪五十年代美国在冷战背景下单方面划定的虚拟界限，中国从一开始就明确否认其存在。",
      "source_sentence_ids": [0, 2]
    },
    {
      "event_id": 1,
      "text": "金门事件中，解放军直接越界开火，证明这条线无法约束中国维护主权的决心。",
      "source_sentence_ids": [3]
    },
    {
      "event_id": 2,
      "text": "进入新世纪，中国实力稳步提升，解放军飞机活动增多，台湾海峡中线的影响力逐步减弱。",
      "source_sentence_ids": [4]
    },
    {
      "event_id": 3,
      "text": "2019年，两架歼-11战机平稳越过台湾海峡中线，台湾地区仅能监视，无法拦截。",
      "source_sentence_ids": [5]
    },
    {
      "event_id": 4,
      "text": "2020年赖清德访美后，轰-6轰炸机绕台湾岛进入太平洋，完全忽略台湾海峡中线，台湾地区飞机只能保持距离观察。",
      "source_sentence_ids": [7]
    },
    {
      "event_id": 5,
      "text": "中国外交部公开声明，台湾海峡不存在此类界限。",
      "source_sentence_ids": [8, 19]
    },
    {
      "event_id": 6,
      "text": "2021年，运-8干扰机和反潜机反复穿越进入台湾西南空域，台湾地区空军派出飞机盘旋，但无力迫使转向，全年进入防空识别区超900次。",
      "source_sentence_ids": [10]
    },
    {
      "event_id": 7,
      "text": "2022年佩洛西访台事件后，解放军启动大规模军演，舰艇列阵推进，军机群包括24架苏-30和6架歼-11越界西北，49架飞机进入识别区越界。",
      "source_sentence_ids": [12]
    },
    {
      "event_id": 8,
      "text": "美国口头抗议但无实质行动，内部承认台湾海峡中线无法律基础，无法约束中国。",
      "source_sentence_ids": [14, 16]
    },
    {
      "event_id": 9,
      "text": "2023年，解放军军机进入台湾防空识别区超1700次，多越界。",
      "source_sentence_ids": [38]
    },
    {
      "event_id": 10,
      "text": "2024年1月，中国民航局调整M503航线，取消偏置，进一步淡化台湾海峡中线界限。",
      "source_sentence_ids": [40]
    },
    {
      "event_id": 11,
      "text": "2024年4月，中国激活W122和W123航线，直飞厦门福州。",
      "source_sentence_ids": [41]
    },
    {
      "event_id": 12,
      "text": "2024年5月赖清德就职后，解放军进行“联合利剑-2024A”演习，37架飞机越界。",
      "source_sentence_ids": [43]
    },
    {
      "event_id": 13,
      "text": "2024年10月，解放军进行“联合利剑-2024B”演习，包围外岛，舰机巡航。",
      "source_sentence_ids": [44]
    },
    {
      "event_id": 14,
      "text": "2025年4月，解放军进行“海峡雷霆-2025A”演习，76架飞机24小时活动，37架越界。",
      "source_sentence_ids": [47]
    },
    {
      "event_id": 15,
      "text": "2025年7月，中国国防部声明，没有所谓台湾海峡中线，重申台湾地区是中国一部分。",
      "source_sentence_ids": [48]
    },
    {
      "event_id": 16,
      "text": "2025年10月，台湾地区报告313架次解放军飞机越界进入防空识别区。",
      "source_sentence_ids": [51]
    }
  ]
}
